import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.DX2KvlNk.js";const u=JSON.parse('{"title":"Releases","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/releases.md","filePath":"contributing/releases.md","lastUpdated":1783503169000}'),o={name:"contributing/releases.md"};function n(l,e,d,r,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h1><p>AOSC ships from <code>develop</code> alone. There are no release branches: <code>develop</code> builds both OpenSearch lines, and each release is cut from a <code>develop</code> commit.</p><p>A release has two version axes:</p><ul><li><strong>AOSC version</strong>: the plugin project version, such as <code>0.1.0</code>. One AOSC version supports both OpenSearch lines.</li><li><strong>OpenSearch minor</strong>: the OpenSearch minor an individual ZIP was built against, such as <code>2.19</code> or <code>3.6</code>.</li></ul><p>The plugin descriptor uses a patch-compatible semver range for the selected OpenSearch minor. For example, a ZIP built with OpenSearch <code>3.6.0</code> is intended for OpenSearch <code>3.6.x</code> unless a release note says otherwise.</p><h2 id="the-version-lives-in-tags" tabindex="-1">The Version Lives in Tags <a class="header-anchor" href="#the-version-lives-in-tags" aria-label="Permalink to &quot;The Version Lives in Tags&quot;">​</a></h2><p><code>develop</code>&#39;s <code>version.properties</code> intentionally stays at a non-release value and never changes for a release:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">aoscVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0.0.0-dev</span></span></code></pre></div><p>The released version is <strong>not</strong> committed to <code>develop</code>. Instead, the <code>Publish Release</code> workflow:</p><ol><li>reads the latest <code>v*</code> tag (<code>git tag --list &#39;v*&#39; --sort=-v:refname</code>),</li><li>applies the chosen <code>patch</code> / <code>minor</code> / <code>major</code> bump to compute the next version, and</li><li>stamps that version into the build with <code>-PaoscVersion=&lt;next&gt;</code> and creates the tag <code>v&lt;next&gt;</code> at publish time.</li></ol><p>If no <code>v*</code> tag exists yet, the first release seeds from <code>0.0.0</code> (so <code>minor</code> produces <code>v0.1.0</code>). This means there are no version-bump commits: the tag history is the version history.</p><h2 id="opensearch-line-manifests" tabindex="-1">OpenSearch Line Manifests <a class="header-anchor" href="#opensearch-line-manifests" aria-label="Permalink to &quot;OpenSearch Line Manifests&quot;">​</a></h2><p>Line-specific build and compatibility data lives in one file per line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>release/os2.properties</span></span>
<span class="line"><span>release/os3.properties</span></span></code></pre></div><p>These are the single source of truth for each line&#39;s supported minors, JDK, Gradle, and dependency pins. Illustrative shape (see the files themselves, or the <a href="./../reference/compatibility">Compatibility reference</a> which renders the current set, for the authoritative values):</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">line</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=os2</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">primary_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2.19.0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">build_versions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2.15.0,…,2.19.0          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># one X.Y.0 per shipped minor</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">test_versions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2.15.0,…,2.19.6           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># every validated patch</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">java_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=11</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">gradle_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=8.7                      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># per-version overrides, e.g. gradle_version.3.7=9.4.1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># plus java_agent, jackson_*, and error_prone.* keys consumed by the build</span></span></code></pre></div><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Property</th><th>Meaning</th></tr></thead><tbody><tr><td><code>build_versions</code></td><td>One version (X.Y.0) per minor that receives a release ZIP. Must cover the same minors as <code>test_versions</code> (enforced by <code>ci-metadata.py</code>).</td></tr><tr><td><code>test_versions</code></td><td>Every released patch covered by CI validation.</td></tr><tr><td><code>java_version</code></td><td>Bytecode target for that line (11 for os2, 21 for os3).</td></tr></tbody></table></div><p>Release ZIP names, CI matrices, and the release build matrix are derived from these files. Do not type OpenSearch versions directly into the workflow.</p><h2 id="cutting-a-release" tabindex="-1">Cutting a Release <a class="header-anchor" href="#cutting-a-release" aria-label="Permalink to &quot;Cutting a Release&quot;">​</a></h2><p>Releases are tag-driven and fully automated from <code>develop</code>:</p><ol><li>Ensure <code>develop</code> is in a releasable state (CI green).</li><li>Run the GitHub <strong>Publish Release</strong> workflow (<code>workflow_dispatch</code>) and pick a <code>bump</code>: <code>patch</code>, <code>minor</code>, or <code>major</code>.</li><li>The workflow computes the next version, validates it does not already exist, runs full validation for both lines at the <code>develop</code> SHA, builds one ZIP per supported minor, and publishes a single GitHub release tagged <code>v&lt;version&gt;</code>.</li><li>Release docs deploy once to <code>/&lt;version&gt;/</code>.</li></ol><p>Choose the bump with the same semantics as before:</p><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Bump</th><th>Use when</th><th>From <code>v0.1.1</code></th></tr></thead><tbody><tr><td><code>patch</code></td><td>Fixes, docs corrections, CI/release fixes, compatibility metadata corrections</td><td><code>v0.1.2</code></td></tr><tr><td><code>minor</code></td><td>New compatible behavior, new settings, new APIs, expanded compatibility</td><td><code>v0.2.0</code></td></tr><tr><td><code>major</code></td><td>Breaking API, behavior, state format, or operational contract changes</td><td><code>v1.0.0</code></td></tr></tbody></table></div><p>The workflow refuses to proceed if the computed tag or release already exists; pick a different bump or remove the stale tag.</p><h2 id="release-pipeline-shape" tabindex="-1">Release Pipeline Shape <a class="header-anchor" href="#release-pipeline-shape" aria-label="Permalink to &quot;Release Pipeline Shape&quot;">​</a></h2><p><code>Publish Release</code> (<code>.github/workflows/publish-release.yml</code>) runs as a singleton (<code>concurrency: publish-release</code>) with these jobs:</p><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Job</th><th>Does</th></tr></thead><tbody><tr><td><code>metadata</code></td><td>Resolves the next version from tags, records the <code>develop</code> SHA, emits the per-minor build matrix, and guards that <code>v&lt;version&gt;</code> is fresh.</td></tr><tr><td><code>validation</code></td><td>Calls <code>components.yml</code> with <code>os_line: all</code>, <code>tier: full</code> at the resolved SHA.</td></tr><tr><td><code>build</code></td><td>Fans out one job per supported minor (JDK per row), runs <code>bundlePlugin -PopensearchVersion=&lt;minor&gt; -PaoscVersion=&lt;version&gt;</code>, and renames the output to <code>opensearch-aosc-&lt;version&gt;-os&lt;minor&gt;.zip</code>.</td></tr><tr><td><code>release-compat</code></td><td>Downloads the built ZIPs and installs each <strong>published</strong> artifact onto a Docker node at its minor&#39;s boundary patches (<code>-Ptests.docker.pluginZip</code>), running the docker smoke suite — validating the shipped bytes across the patches they claim. Gates <code>publish</code>.</td></tr><tr><td><code>publish</code></td><td>Gathers all ZIPs, writes <code>SHA256SUMS</code> and release notes, attests provenance, and runs <code>gh release create v&lt;version&gt; --target &lt;sha&gt;</code> (which creates the tag atomically). Runs in the <code>release</code> environment. Needs <code>validation</code>, <code>build</code>, and <code>release-compat</code>.</td></tr><tr><td><code>deploy_docs</code></td><td>Deploys the docs once to <code>/&lt;version&gt;/</code>.</td></tr></tbody></table></div><p>Every ZIP for every minor of both lines is built and validated at the same <code>develop</code> commit, so a release is a coherent snapshot rather than an accumulation across branches.</p><h2 id="github-release-assets" tabindex="-1">GitHub Release Assets <a class="header-anchor" href="#github-release-assets" aria-label="Permalink to &quot;GitHub Release Assets&quot;">​</a></h2><p>Each <code>v&lt;version&gt;</code> release contains, for both lines:</p><ul><li>one plugin ZIP per supported OpenSearch minor, named <code>opensearch-aosc-&lt;version&gt;-os&lt;minor&gt;.zip</code></li><li><code>SHA256SUMS</code></li><li>release notes with download and compatibility guidance</li><li>build provenance attestation</li></ul><p>Example asset shape for <code>v0.1.0</code> (one ZIP per supported minor — the exact set is whatever the manifests declare at release time; see the <a href="./../reference/compatibility">Compatibility reference</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opensearch-aosc-0.1.0-os2.15.zip</span></span>
<span class="line"><span>opensearch-aosc-0.1.0-os2.17.zip</span></span>
<span class="line"><span>…</span></span>
<span class="line"><span>opensearch-aosc-0.1.0-os3.6.zip</span></span>
<span class="line"><span>opensearch-aosc-0.1.0-os3.7.zip</span></span>
<span class="line"><span>SHA256SUMS</span></span></code></pre></div><p>Download the ZIP matching your OpenSearch minor. A <code>3.6</code> ZIP is intended for the <code>3.6.x</code> patch line unless a release note says otherwise.</p><h2 id="github-actions" tabindex="-1">GitHub Actions <a class="header-anchor" href="#github-actions" aria-label="Permalink to &quot;GitHub Actions&quot;">​</a></h2><p>The workflow files are split by the reason a workflow runs:</p><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Workflow</th><th>File</th><th>Trigger</th><th>Publishes?</th></tr></thead><tbody><tr><td>Pull Request</td><td><code>.github/workflows/pull-request.yml</code></td><td>Pull requests targeting <code>develop</code></td><td>No</td></tr><tr><td>Branch: develop</td><td><code>.github/workflows/branch-develop.yml</code></td><td>Pushes to <code>develop</code></td><td>Publishes <code>/develop/</code> docs after validation passes</td></tr><tr><td>Publish Release</td><td><code>.github/workflows/publish-release.yml</code></td><td>Manual dispatch (<code>bump</code> input)</td><td>Publishes the <code>v&lt;version&gt;</code> GitHub release and <code>/&lt;version&gt;/</code> docs</td></tr><tr><td>Components</td><td><code>.github/workflows/components.yml</code></td><td>Reusable workflow only</td><td>No</td></tr></tbody></table></div><p><code>components.yml</code> builds a matrix over both lines&#39; minors (each row carries <code>opensearch_version</code>, <code>java_version</code>, and an unqualified Gradle task run with <code>-PopensearchVersion</code>). A <code>tier</code> input (<code>fast</code> | <code>full</code>) controls breadth. Full validation runs these suites as separate jobs so a failure identifies the exact minor and suite:</p><ul><li>fast checks</li><li>YAML REST tests</li><li>Java integration tests</li><li>2-node smoke tests</li><li>dedicated cluster-manager smoke tests</li><li>Docker smoke tests</li><li>high-shard 2-node scale tests</li></ul><h2 id="building-locally" tabindex="-1">Building Locally <a class="header-anchor" href="#building-locally" aria-label="Permalink to &quot;Building Locally&quot;">​</a></h2><p>Build a ZIP for one OpenSearch minor:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundlePlugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PopensearchVersion=3.6.0</span></span></code></pre></div><p>Stamp a specific release version into the descriptor (as the release workflow does):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundlePlugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PopensearchVersion=3.6.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -PaoscVersion=0.1.0</span></span></code></pre></div><p>Inspect the release metadata the workflow uses:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/ci-metadata.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build-matrix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/ci-metadata.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --next-version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minor</span></span></code></pre></div><h2 id="documentation-site" tabindex="-1">Documentation Site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation Site&quot;">​</a></h2><p>GitHub Pages uses VitePress. Pull requests build the docs as CI validation only; they do not publish the site.</p><p>The docs workflows store versioned site output on the <code>gh-pages</code> branch, then deploy the complete site with GitHub Pages Actions. The GitHub Pages repository setting should use GitHub Actions as the source.</p><p>Docs are versioned by AOSC version only (no OpenSearch line suffix), following two simple rules:</p><ul><li>Pushes to <code>develop</code> publish the current development docs to <code>/develop/</code> after validation passes.</li><li>Each release <code>v&lt;version&gt;</code> deploys its docs once to <code>/&lt;version&gt;/</code>.</li></ul><p><code>versions.json</code> on <code>gh-pages</code> is the authoritative list of published versions; the deploy script maintains it and the theme builds the version switcher from it at runtime. The site config carries only a placeholder switcher entry that the theme replaces — no concrete version list is hand-maintained.</p><p>Build the docs locally with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>The docs deploy script owns the generated <code>versions.json</code> and root redirect on <code>gh-pages</code>; do not edit those files by hand.</p><h2 id="ci-artifacts" tabindex="-1">CI Artifacts <a class="header-anchor" href="#ci-artifacts" aria-label="Permalink to &quot;CI Artifacts&quot;">​</a></h2><p>CI uploads Gradle reports and test results only when a validation job fails. Normal CI artifacts expire after 7 days; publish workflow artifacts expire after 14 days. Release ZIPs are not CI artifacts; they are attached to the GitHub release.</p><h2 id="runtime-version-checks" tabindex="-1">Runtime Version Checks <a class="header-anchor" href="#runtime-version-checks" aria-label="Permalink to &quot;Runtime Version Checks&quot;">​</a></h2><p>Installed plugin versions can be checked with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://localhost:9200/_cat/plugins?v&#39;</span></span></code></pre></div><p>A built ZIP descriptor can be inspected with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/build/distributions/opensearch-aosc-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin-descriptor.properties</span></span></code></pre></div><h2 id="first-public-import" tabindex="-1">First Public Import <a class="header-anchor" href="#first-public-import" aria-label="Permalink to &quot;First Public Import&quot;">​</a></h2><p>Public GitHub history starts from the OSS import. Earlier internal development history is not part of the public repository.</p>`,64)])])}const b=s(o,[["render",n]]);export{u as __pageData,b as default};
